export const routes: Routes = [
  { path: 'tareas', component: ListaTareas },
  { path: 'tareas/:id', component: DetalleTarea },
  {
    path: 'reportes',
    loadComponent: () => import('./reportes/reportes').then(m => m.Reportes),
  },
];

// app.config.ts
provideRouter(routes, withComponentInputBinding())

// detalle-tarea.ts
export class DetalleTarea {
  readonly id = input.required<string>();   // mismo nombre que :id
  private readonly store = inject(TareasStore);
  readonly tarea = computed(() => this.store.tareas().find(t => t.id === this.id()));
}

